export interface CmsPageSeo { metaTitle: string | null; metaDescription: string | null; metaKeywords: string | null; openGraphImageUrl: string | null }
export interface CmsPageTranslation { title: string; contentType: string; content: string | unknown[]; schemaVersion: number; seo: CmsPageSeo; [key: string]: unknown }
export interface CmsPageVersion { recordId: string; slug: string; version: number; contentType: string; seo: CmsPageSeo; translations?: { en: CmsPageTranslation; ar: CmsPageTranslation | null }; [key: string]: unknown }
export function deriveCurrentCmsPageIdentityPresentation<T>(page: T, currentUser: unknown, options?: { expectedPageId?: string }): (Omit<T, 'id' | 'tenantId' | 'slug' | 'draft' | 'published'> & { id: string; tenantId: string; slug: string; draft: CmsPageVersion | null; published: CmsPageVersion | null }) | null;
export function deriveCurrentCmsPageListPresentation<T>(pages: T[], currentUser: unknown): (T & { id: string; tenantId: string; slug: string })[] | null;
export function deriveCurrentCmsPageVersionHistoryPresentation<T>(history: T, currentUser: unknown, options?: { expectedPageId?: string }): (Omit<T, 'pageId' | 'tenantId' | 'currentDraftVersion' | 'publishedVersion' | 'versions'> & { pageId: string; tenantId: string; currentDraftVersion: number | null; publishedVersion: number | null; versions: { version: number; snapshot: CmsPageVersion; isCurrentDraft: boolean; isPublished: boolean; [key: string]: unknown }[] }) | null;
